import { ok, fail } from './result.js';
import { roundCents } from './money.js';
import { getCustomer, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Calculate the total amount for a line: qty × unitPrice (in cents), before discount.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a line: lineTotal × (discountPercent / 100).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  const discount = lineTotal(line) * ((line.discountPercent || 0) / 100);
  return Math.max(0, roundCents(discount));
}

/**
 * Calculate the VAT for a line: (lineTotal - lineDiscount) × (vatRate / 100).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {number}
 */
export function lineVat(line) {
  const amountAfterDiscount = lineTotal(line) - lineDiscount(line);
  const vat = amountAfterDiscount * ((line.vatRate || 0) / 100);
  return Math.max(0, roundCents(vat));
}

/**
 * Calculate invoice totals: subtotal, discount, VAT, and total (after discount and VAT).
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const total = Math.max(0, subtotal - discount + vat);
  return {
    subtotal: Math.max(0, subtotal),
    discount: Math.max(0, discount),
    vat: Math.max(0, vat),
    total
  };
}

/**
 * Validate a discount percent value.
 * @param {unknown} discountPercent
 * @returns {{ ok: true } | { ok: false, error: string }}
 */
function validateDiscount(discountPercent) {
  if (discountPercent === undefined || discountPercent === null) return { ok: true };
  if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
    return { ok: false, error: 'DISCOUNT_INVALID' };
  }
  return { ok: true };
}

/**
 * Create a draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: 'draft', lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  if (!lines || lines.length === 0) return fail('NO_LINES');

  const dateValid = /^\d{4}-\d{2}-\d{2}$/.test(issueDate);
  if (!dateValid) return fail('DATE_INVALID');

  const dateParts = issueDate.split('-');
  const year = Number(dateParts[0]);
  const month = Number(dateParts[1]);
  const day = Number(dateParts[2]);
  const date = new Date(year, month - 1, day);
  if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) {
    return fail('DATE_INVALID');
  }

  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;
  const invoiceLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    const discountValidation = validateDiscount(line.discountPercent);
    if (!discountValidation.ok) return fail(discountValidation.error);

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const finalDiscount = line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: finalDiscount,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

/**
 * Add or update a line on a draft invoice.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {{ ok: true, value: Object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  const discountValidation = validateDiscount(discountPercent);
  if (!discountValidation.ok) return fail(discountValidation.error);

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  const existingIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingIndex >= 0) {
    newLines[existingIndex] = {
      ...newLines[existingIndex],
      qty: newLines[existingIndex].qty + qty,
    };
  } else {
    const customerResult = getCustomer(invoice.customerId);
    if (!customerResult.ok) return customerResult;

    const customer = customerResult.value;
    const finalDiscount = discountPercent !== undefined ? discountPercent : TIER_DISCOUNTS[customer.tier];
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: finalDiscount,
    });
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: Object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku).map((line) => ({ ...line }));

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing its status to 'issued'.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {Array<string>} existingNumbers - Array of invoice numbers already used
 * @returns {{ ok: true, value: Object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    number,
    lines: invoice.lines.map((line) => ({ ...line })),
  });
}

